declare namespace SigApi {
    interface PermissionObj {
        /**
         * true if permission to create users
         */
        readonly createUser: boolean
        /**
         * true if permission to update/change users
         */
        readonly updateUser: boolean
        /**
         * true if permission to delete users
         */
        readonly deleteUser: boolean
        /**
         * true if permission to import users
         */
        readonly importUsers: boolean
        /**
         * true if permission to login at client
         */
        readonly loginAtClient: boolean
        /**
         * true if permission to create roles
         */
        readonly createRole: boolean
        /**
         * true if permission to update/change roles
         */
        readonly updateRole: boolean
        /**
         * true if permission to delete roles
         */
        readonly deleteRole: boolean
        /**
         * true if permission to import roles
         */
        readonly importRoles: boolean
        /**
         * true if permission to grant roles to users
         */
        readonly grantRole: boolean
        /**
         * true if permission to change own user name
         */
        readonly updateOwnUsername: boolean
        /**
         * true if permission to change own user password
         */
        readonly updateOwnPW: boolean
        /**
         * true if permission to change own user data
         */
        readonly updateOwnInfo: boolean
        /**
         * true if permission to delete users permanently
         */
        readonly deleteUserPermanent: boolean
    }
}
